<?php
declare(strict_types=1);
require_once '../config/config.php'; require_once '../includes/church-book-functions.php';
if(!isset($conn)||!($conn instanceof mysqli))die('Database connection not found.'); $conn->set_charset('utf8mb4');
$token=cb_clean($_GET['token']??$_POST['token']??''); $invite=cb_registration_link_lookup($conn,'visitor_registration_links',$token,false); $csrf=cb_csrf_token(); $errors=[]; $success=false;
$site=cb_site_setting($conn,'site_name','Church'); $logo=cb_site_setting($conn,'site_logo',cb_site_setting($conn,'logo','')); if($logo!==''&&!preg_match('~^https?://~i',$logo))$logo=cb_absolute_base_url().ltrim($logo,'/');
if($_SERVER['REQUEST_METHOD']==='POST'&&$invite){
 cb_verify_csrf();
 $date=cb_clean($_POST['visit_date']??date('Y-m-d')); $name=cb_clean($_POST['full_name']??''); $gender=cb_clean($_POST['gender']??''); $phone=cb_clean($_POST['phone']??''); $email=cb_clean($_POST['email']??''); $address=cb_clean($_POST['address']??''); $type=cb_clean($_POST['visitor_type']??'First Time'); $service=cb_clean($_POST['service_attended']??''); $invited=cb_clean($_POST['invited_by']??''); $reason=cb_clean($_POST['reason_for_visit']??''); $prayer=cb_clean($_POST['prayer_request']??''); $notes=cb_clean($_POST['notes']??'');
 if($name===''||!cb_valid_date($date))$errors[]='Your full name and a valid visit date are required.'; if($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='Enter a valid email address.';
 if(!in_array($type,['First Time','Returning'],true))$type='First Time'; if(!in_array($gender,['Male','Female','Other','Prefer not to say'],true))$gender=null;
 if(!$errors){$conn->begin_transaction();try{$locked=cb_registration_link_lookup($conn,'visitor_registration_links',$token,true);if(!$locked)throw new RuntimeException('This registration link is no longer available.');$linkId=(int)$locked['id'];$followReq=0;$follow='Not Required';$assigned=null;$createdBy=null;$prefix='Self-registered using public visitor registration link.';$notes=trim($prefix.($notes!==''?' '.$notes:''));
 $stmt=$conn->prepare("INSERT INTO church_visitors(visit_date,member_id,full_name,gender,phone,email,address,visitor_type,service_attended,invited_by,reason_for_visit,prayer_request,follow_up_required,follow_up_status,assigned_to,notes,self_registered,registration_link_id,created_by) VALUES(?,NULL,?,?,?,?,?,?,?,?,?,?,?,?,?,?,1,?,NULL)");
 if(!$stmt)throw new RuntimeException('Unable to prepare visitor registration.');$stmt->bind_param('sssssssssssisssi',$date,$name,$gender,$phone,$email,$address,$type,$service,$invited,$reason,$prayer,$followReq,$follow,$assigned,$notes,$linkId);if(!$stmt->execute())throw new RuntimeException('Unable to save registration: '.$stmt->error);$stmt->close();cb_consume_registration_link($conn,'visitor_registration_links',$locked);$conn->commit();$success=true;}catch(Throwable $e){$conn->rollback();$errors[]=$e->getMessage();}}
}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Visitor Registration - <?= cb_h($site) ?></title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css"><link rel="stylesheet" href="../assets/css/public-registration.css"><?= site_theme_css() ?></head><body><div class="pr-wrap"><div class="pr-card"><div class="pr-head"><?php if($logo):?><img class="pr-logo" src="<?= cb_h($logo) ?>" alt="<?= cb_h($site) ?> Logo"><?php endif;?><h1>Church Visitor Registration</h1><p><?= cb_h($site) ?></p></div><div class="pr-body">
<?php if($success):?><div class="pr-success-card"><i class="fas fa-circle-check"></i><h2>Registration received</h2><p>Thank you. Your visitor details have been submitted successfully.</p></div>
<?php elseif(!$invite):?><div class="pr-disabled"><div class="pr-alert pr-error">This registration invitation is invalid, expired, inactive, or has reached its usage limit.</div><p>Please request a new link from the church office.</p></div>
<?php else:?><?php foreach($errors as $e):?><div class="pr-alert pr-error"><?= cb_h($e) ?></div><?php endforeach;?><p class="pr-note">Complete the form below. Fields marked * are required.</p><form method="post"><input type="hidden" name="csrf_token" value="<?= cb_h($csrf) ?>"><input type="hidden" name="token" value="<?= cb_h($token) ?>"><div class="pr-grid">
<div class="pr-field"><label>Visit Date *</label><input class="pr-input" type="date" name="visit_date" value="<?= cb_h($_POST['visit_date']??date('Y-m-d')) ?>" required></div><div class="pr-field"><label>Visitor Type *</label><select class="pr-select" name="visitor_type"><option>First Time</option><option <?= ($_POST['visitor_type']??'')==='Returning'?'selected':'' ?>>Returning</option></select></div>
<div class="pr-field"><label>Full Name *</label><input class="pr-input" name="full_name" required maxlength="180" value="<?= cb_h($_POST['full_name']??$invite['recipient_name']??'') ?>"></div><div class="pr-field"><label>Gender</label><select class="pr-select" name="gender"><option value="">Select</option><?php foreach(['Male','Female','Other','Prefer not to say'] as $g):?><option <?= ($_POST['gender']??'')===$g?'selected':'' ?>><?= cb_h($g) ?></option><?php endforeach;?></select></div>
<div class="pr-field"><label>Phone</label><input class="pr-input" name="phone" maxlength="50" value="<?= cb_h($_POST['phone']??$invite['recipient_phone']??'') ?>"></div><div class="pr-field"><label>Email</label><input class="pr-input" type="email" name="email" maxlength="180" value="<?= cb_h($_POST['email']??'') ?>"></div>
<div class="pr-field span-2"><label>Address / Residence</label><input class="pr-input" name="address" maxlength="255" value="<?= cb_h($_POST['address']??'') ?>"></div><div class="pr-section">Visit Details</div>
<div class="pr-field"><label>Service / Program Attended</label><input class="pr-input" name="service_attended" maxlength="180" value="<?= cb_h($_POST['service_attended']??'') ?>"></div><div class="pr-field"><label>Who Invited You?</label><input class="pr-input" name="invited_by" maxlength="180" value="<?= cb_h($_POST['invited_by']??'') ?>"></div><div class="pr-field span-2"><label>Reason for Visit</label><input class="pr-input" name="reason_for_visit" maxlength="255" value="<?= cb_h($_POST['reason_for_visit']??'') ?>"></div><div class="pr-field span-2"><label>Prayer Request</label><textarea class="pr-textarea" name="prayer_request"><?= cb_h($_POST['prayer_request']??'') ?></textarea></div><div class="pr-field span-2"><label>Additional Notes</label><textarea class="pr-textarea" name="notes"><?= cb_h($_POST['notes']??'') ?></textarea></div></div><div class="pr-actions"><button class="pr-btn" type="submit"><i class="fas fa-paper-plane"></i> Submit Registration</button></div></form><?php endif;?></div></div></div></body></html>
